import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {spawnSync, execFileSync} from 'node:child_process';
import os from 'node:os';
import path from 'node:path';

// Exact canonical stdout is the CLI contract, including its final newline.
// Alternative valid CSV quoting is outside this presentation regression grader.
const hash = text => crypto.createHash('sha256').update(text).digest('hex');
const grade = (actual, expected) => actual === expected;
assert(grade('"a,b",c\n', '"a,b",c\n'));
assert(!grade('a,b,c\n', '"a,b",c\n'));
assert(!grade('a,b \n', 'a,b\n'));
assert(!grade('a,b', 'a,b\n'));
assert(!grade('"a",b\n', 'a,b\n')); // deliberately narrower than semantic CSV
const casesText = fs.readFileSync('tests/cases.json', 'utf8');
const cases = JSON.parse(casesText);
const source = fs.readFileSync('app.mjs', 'utf8');
const old = execFileSync('git', ['show', 'f8ebf1f:app.mjs'], {encoding:'utf8'});
const conditions = [
  {id:'historical-default', source:old, args:[]},
  {id:'historical-full', source:old, args:['full']},
  {id:'baseline', source, args:['baseline']},
  {id:'full', source, args:['full']},
  {id:'without-unicode', source, args:['without-unicode']},
  {id:'without-escaping', source, args:['without-escaping']},
  {id:'current-default', source, args:[]}
];
const settings = {runtime:process.version, grader:'exact stdout; exit 0; no stderr', casesSha256:hash(casesText),
  conditions:conditions.map(({id,source,args}) => ({id,sourceSha256:hash(source),args}))};
const replay = process.argv[2] === '--replay';
if (replay) {
  const saved = JSON.parse(fs.readFileSync('evidence/results.json','utf8'));
  assert.deepEqual(saved.settings, settings, 'sources, inputs or runtime changed; regenerate observations');
  for (const row of saved.results) {
    const task = cases.find(c => c.id === row.case);
    assert(task);
    assert.equal(row.pass, row.status === 0 && row.signal === null && row.stderr === '' && grade(row.stdout, task.expected));
  }
  assert.deepEqual(saved.results.map(r => [r.case,r.condition]), cases.flatMap(c => conditions.map(k => [c.id,k.id])));
  console.log(`Replayed ${saved.results.length} saved ratings.`);
} else {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'csv-review-'));
  const results = [];
  try {
    // Freeze both source snapshots before any execution; interleave by case.
    for (const condition of conditions) fs.writeFileSync(path.join(dir, condition.id+'.mjs'), condition.source);
    for (const task of cases) for (const condition of conditions) {
      const run = spawnSync(process.execPath, [path.join(dir, condition.id+'.mjs'), JSON.stringify(task.input), ...condition.args], {encoding:'utf8',timeout:5000});
      if (run.error) throw run.error; // infrastructure failures are not behavioral failures
      const pass = run.status === 0 && run.signal === null && run.stderr === '' && grade(run.stdout, task.expected);
      results.push({case:task.id,condition:condition.id,stdout:run.stdout,stderr:run.stderr,status:run.status,signal:run.signal,pass,
        reason:pass ? 'Exact ordered CSV and successful execution' : run.status !== 0 ? 'Execution failure' : 'Output differs from canonical ordered CSV'});
    }
  } finally { fs.rmSync(dir, {recursive:true,force:true}); }
  fs.mkdirSync('evidence',{recursive:true});
  fs.writeFileSync('evidence/results.json', JSON.stringify({settings,results},null,2)+'\n');
  for (const condition of conditions) {
    const rows = results.filter(r => r.condition === condition.id);
    console.log(`${condition.id}: ${rows.filter(r => r.pass).length}/${rows.length}`);
  }
  assert(results.filter(r => ['full','current-default'].includes(r.condition)).every(r => r.pass));
}
EOF
